    'tujajure' => array (
  0 => 
  array (
    't' => 'Agaca gacakiye agahori gati:',
    'p' => 'Mwana wa mama undiye twari bamwe.',
  ),
  1 => 
  array (
    't' => 'Agaca gacakiye agahori gati:',
    'p' => 'Nagira ngo akaguruka ntikoriye akandi.',
  ),
  2 => 
  array (
    't' => 'Agaca gacakiye agahori gati, kano kati:',
    'p' => 'Urandya neza ndahanda.',
  ),
  3 => 
  array (
    't' => 'Agahume gahwaniye n\'akandi mu mwonga ngo:',
    'p' => 'Rinda tubane waragowe ndagorwa.',
  ),
  4 => 
  array (
    't' => 'Agakara kagiye iwa sebukwe ngo agataramure kano gahitanywe gaca mu mbavu ati:',
    'p' => 'Ni wewe ga mupfaso? Na ko ngo ego agakara gasa n\'akandi.',
  ),
  5 => 
  array (
    't' => 'Agakecuru kasanze akandi mu kuzimu kati:',
    'p' => 'Nyereka ibigega wimbuye. Na ko kati: Noneho ngaho mama uraje kuvyiyimburira nawe.',
  ),
  6 => 
  array (
    't' => 'Agakecuru kashikuye igikoba kigata ku kingi kati:',
    'p' => 'Nakudya ntitwarwana.',
  ),
  7 => 
  array (
    't' => 'Agakecuru karose gapfa gati:',
    'p' => 'Maze simvyanka.',
  ),
  8 => 
  array (
    't' => 'Akagomba kaneye mu cibo kati:',
    'p' => 'Urantuma mugabo wa mama ishikanwa ry\'umworo ni iryo.',
  ),
  9 => 
  array (
    't' => 'Akagomba kenzwe na se kati:',
    'p' => 'N\'uburi mu mwonga nibushoke.',
  ),
  10 => 
  array (
    't' => 'Urunyegeri rwamenekanye n\'intango ruti:',
    'p' => 'Abenga ni benge jeho ndenguye.',
  ),
  11 => 
  array (
    't' => 'Babajije gikona bati: «Mbega gikona ko ugenda wasamye?» Giti:',
    'p' => 'Ntawumenya iyo indya zituruka.',
  ),
  12 => 
  array (
    't' => 'Ikirogorye cagiye gusaba amazi kw\'ijuru, inkuba iti: «Twa!» Giti:',
    'p' => 'Iyo mbura amazi ngakiza igufa.',
  ),
  13 => 
  array (
    't' => 'Babariye Samandari bati: «Urabona ga Samandari ukarya inkenekene zimena amaso?» Ati:',
    'p' => 'Ubusa bwo?',
  ),
  14 => 
  array (
    't' => 'Ikirogorye canyereye ku gishishwa, kiragwa, giti:',
    'p' => 'Haborewe jewe, hari akantu abaruganye!',
  ),
  15 => 
  array (
    't' => 'Imbwa yahuye n\'umusaza, abura ico ayiha, iti:',
    'p' => 'Haguhura n\'umusaza wohura n\'umwana, abura ico aguha akaguherekeza canke akakwirukana.',
  ),
),
];
